head.script:
scwin.onpageload = function() {
    console.log("onpageload " + $p.getFrameId() + " Frame =========================================================== ");
    // $p.getRuntimeId("scwin", "parent")를 호출하면 scwin 객체의 아이디가 현재 팝업창(popup_wframe2.xml)을 
    // 호출한 상위 팝업(poup_wframe1.xml)의 scwin 객체 아이디가 아닌 최상위 프레임의 scwin 객체 아이디가 반환된다.
    console.log("$p.getRuntimeId(\"scwin\", \"parent\") : " + $p.getRuntimeId("scwin", "parent"));
    localStorage.setItem("window.log1", "$p.getRuntimeId(\"scwin\", \"parent\") : " + $p.getRuntimeId("scwin", "parent"));
    WebSquare.logger.printLog("$p.getRuntimeId(\"scwin\", \"parent\") : " + $p.getRuntimeId("scwin", "parent"));
    // $p.parent().scwin 에 접근하면 현재 팝업창(popup_wframe2.xml)을 호출한 상위 팝업(poup_wframe1.xml)의 scwin 객체가
    // 아닌 최상위 프레임의 scwin 객체가 반환된다.
    console.log("$p.parent().$p.getFrameId() : " + $p.parent().$p.getFrameId());
    localStorage.setItem("window.log2", "$p.parent().$p.getFrameId() : " + $p.parent().$p.getFrameId());
    WebSquare.logger.printLog("$p.parent().$p.getFrameId() : " + $p.parent().$p.getFrameId());
    console.log("$p.parent().scwin.popupId : " + $p.parent().scwin.popupId);
    localStorage.setItem("window.log3", "$p.parent().scwin.popupId : " + $p.parent().scwin.popupId);
    WebSquare.logger.printLog("$p.parent().scwin.popupId : " + $p.parent().scwin.popupId);
    console.log("========================================================================================== ");
};
scwin.onpageunload = function() {};
scwin.grd_memberList_onrowindexchange = function(row, oldRow) {
    var id = $p.parent().dlt_memberList.getCellData(row, "id");
    var name = $p.parent().dlt_memberList.getCellData(row, "name");
    ibx_idName2.setValue("Popup2 - [" + id + "] - " + name);
};
scwin.btn_trigger1_onclick = function(e) {
    var wfr = common.getPopupFrame(scwin.param.parentPopupId);
    wfr.getObj("scwin").setIdName(ibx_idName2.getValue());
    //alert(wfr.getObj("ibx_idName1").getValue());  // 부모 팝업 창에 ibx_idName1 컴포넌트에 접근
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.common = {};
    /**
     * popupId에 해당하는 팝업 프레임 객체를 반환한다.
     * @param {String} popupId 팝업 아이디
     * @return {Object} 팝업 프레임 객체
     */
    common.getPopupFrame = function(popupId) {
        return $p.getPopup(popupId).popupWin.frame;
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
